def receipt(j,rc,*,persist=True,**fields):
    global RECEIPTED
    action = fields.pop('action',None)
    if 'reason' in fields: fields['reason']=redact(fields['reason'])
    if isinstance(action,str) and (len(action)>80 or is_secret(action)): action={'sha256':hashlib.sha256(action.encode()).hexdigest()}
    if 'run_id' not in j:
        j['run_id']=uuid.uuid4().hex; save(j)
    r=dict(schema='vis.receipt/v1',job=j['job'],run_id=j['run_id'],step=getattr(ARGS,'step',None),verb=ARGS.verb,action=action,
           target_kind=j['target_kind'],display=j['display'],ownership=j['ownership'],frame_sha_before=None,frame_sha_after=None,
           expected=getattr(ARGS,'expect_change',None),changed_regions=[],verdict='pass' if rc==0 else ('refused' if rc in (2,4,5) else 'fail'),
           rc=rc,code=CODES[rc],attempts=j.get('steps',{}).get(getattr(ARGS,'step',None),{}).get('attempts',0),attempts_scope='per_step_id',
           ref_wa=j.get('engines',{}).get('wender_ref'),ref_ve=j.get('engines',{}).get('ve_ref'),t_ms=int((time.monotonic()-START)*1000))
    if ARGS.verb=='act': r['loop_witness']=j.get('loop_witness',dict(before=None,after=None,obtained=False))
    if ARGS.verb=='check' and (getattr(ARGS,'state',None) or getattr(ARGS,'state_absent',None)):
        operand=ARGS.state or ARGS.state_absent
    if a.verb=='look':
        frame=capture(j); d=describe(j,frame)
        if j['target_kind']=='web': d['state']=state_observation(j)
        save_last(j,d); receipt(j,0,frame_sha_after=d['frame_sha256']); prune_frames(j); return d
    if a.verb=='check': return do_check(j,a)
    fail(2,'unknown verb')

def region_hash(path,box):
    w,h,rgb=pixels(path);x,y,bw,bh=box
    if x+bw>w or y+bh>h: fail(2,'region outside surface')
    return hashlib.sha256(b''.join(rgb[(row*w+x)*3:(row*w+x+bw)*3] for row in range(y,y+bh))).hexdigest()

def do_check(j,a):
    target(j)
    if not 2<=a.require_stable<=20: fail(2,'--require-stable must be between 2 and 20')
    baseline=None; box=None
